{"command": "cd /testbed && cat > /tmp/test_pr.py <<'EOF'
import numpy as np
import sys

def test_array_interface_refcount_shapes():
    # See gh-xxxxx
    class MyArray:
        def __init__(self, data):
            self.data = data

    class MyArray2:
        def __init__(self, data):
            self.data = data
        def __array__(self, dtype=None):
            return np.asarray(self.data)

    for arr in [
        np.array([1, 2, 3]),
        np.arange(6).reshape(2, 3),
        np.zeros(2),
        np.float64(5.0),
    ]:
        arr = np.array(arr)
        iface = arr.__array_interface__
        shape = iface['shape']
        iface['shape'] = (-1,)  # negative shape to trigger failure path
        d = np.dtype(iface['typestr'])
        refcount = sys.getrefcount(d)
        try:
            np.array(MyArray())
        except ValueError:
            pass
        assert sys.getrefcount(d) == refcount

# direct per-case checks
def run():
    d = np.dtype('float64')
    base = sys.getrefcount(d)

    class A:
        __array_interface__ = {'typestr': '|f8', 'shape': (1, -1)}
    try:
        np.array(A())
    except ValueError as e:
        print("shape:", e)
    assert sys.getrefcount(d) == base, sys.getrefcount(d) - base

    buf = bytearray(64)

    class B:
        __array_interface__ = {'typestr': '|f8', 'shape': (2, 2), 'strides': (8,), 'data': buf}
    try:
        np.array(B())
    except ValueError as e:
        print("strides mismatch:", e)
    assert sys.getrefcount(d) == base

    class C:
        __array_interface__ = {'typestr': '|f8', 'shape': (2, 2), 'strides': 5, 'data': buf}
    try:
        np.array(C())
    except TypeError as e:
        print("strides not tuple:", e)
    assert sys.getrefcount(d) == base

    class D:
        __array_interface__ = {'typestr': '|f8', 'shape': (2, 2), 'strides': ('a','b'), 'data': buf}
    try:
        np.array(D())
    except TypeError as e:
        print("strides bad val:", e)
    assert sys.getrefcount(d) == base
    print("ALL GOOD")

run()
EOF
