import numpy as np
import sys

def check(label, cls, exc):
    d = np.dtype('float64')
    b = sys.getrefcount(d)
    try:
        np.array(cls())
        result = "NO ERROR"
    except Exception as e:
        result = "%s: %s" % (type(e).__name__, e)
    a = sys.getrefcount(d)
    print("%-28s %-55s delta=%d" % (label, result, a - b))
    assert isinstance(sys.exc_info()[1], type(None)) or True
    assert a == b, "refcount corruption in " + label
    assert result.startswith(exc), "expected %s got %s" % (exc, result)

class PropShape:
    @property
    def __array_interface__(self):
        return {'typestr': '|f8', 'shape': (1, -1), 'data': (0, False)}

class PropStridesMismatch:
    @property
    def __array_interface__(self):
        return {'typestr': '|f8', 'shape': (2, 2), 'strides': (8,), 'data': bytearray(32)}

class ScalarTooBig:
    # no data -> scalar fill; size > 1 triggers failure
    __array_interface__ = {'typestr': '|f8', 'shape': (2, 2)}

check("property negative shape", PropShape, "ValueError")
check("property strides mismatch", PropStridesMismatch, "ValueError")
check("scalar size>1", ScalarTooBig, "ValueError")
print("ALL GOOD")
EOF
PYTHONPATH=/testbed python3 /tmp/repro3.py"}

